def weights_init(m):
    classname = m.__class__.__name__
    if classname.find('Linear') != -1:
        torch.nn.init.normal_(m.weight.data, 0.0, 0.02)
        if m.bias is not None:
            torch.nn.init.constant_(m.bias.data, 0)
    elif classname.find('GRU') != -1:
        for param in m.parameters():
            if len(param.shape) >= 2:
                torch.nn.init.orthogonal_(param.data)
            else:
                torch.nn.init.normal_(param.data)

def compute_gradient_penalty(D, real_condition, real_samples, fake_samples):
    """Menghitung gradient penalty untuk WGAN-GP (Conditional)"""
    alpha = torch.rand(real_samples.size(0), 1, 1, device=torch.device)
    alpha = alpha.expand_as(real_samples)
    interpolated = (alpha * real_samples + (1 - alpha) * fake_samples).requires_grad_(True)
    with torch.backends.cudnn.flags(enabled=False):
        d_interpolated = D(real_condition, interpolated)
    grad_outputs = torch.ones(d_interpolated.size(), device=torch.device, requires_grad=False)
    gradients = torch.autograd.grad(outputs=d_interpolated, inputs=interpolated, grad_outputs=grad_outputs, create_graph=True, retain_graph=True, only_inputs=True)[0]
    gradients = gradients.reshape(gradients.size(0), -1)
    gradient_penalty = ((gradients.norm(2, dim=1) - 1) ** 2).mean()
    return gradient_penalty

